// EFIOpenAndFill opens a stream as [Core.EFIOpen] does and also writes the
// outputs over the whole history, as [Core.EFI] writes them for bars 0 through
// len(inClose)-1, returning that range.
//
// Each output must hold len(inClose) minus [Core.EFILookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.EFIOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) EFIOpenAndFill(inClose, inVolume []float64, optInTimePeriod int, outReal []float64) (*EFIStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.efiLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inVolume) != len(inClose) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inClose)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inClose) || sameStart(outReal, inVolume) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inClose) || overlaps(outReal, inVolume)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.efiOpenAndFillInternal(inClose, inVolume, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
